CREATE VIEW std_inventory_enriched AS SELECT s.*, mas.canonical_value AS acquisition_source, mps.canonical_value AS play_status, CASE  WHEN ((s.play_status_raw = 'Removed')) THEN ('Removed') WHEN ((s.owned_flag = CAST('t' AS BOOLEAN))) THEN ('Available') ELSE 'Unknown' END AS access_status, msl.canonical_value AS storage_location FROM std_all_inventory AS s LEFT JOIN map_acquisition_source AS mas ON ((s.acquisition_source_raw = mas.raw_value)) LEFT JOIN map_play_status AS mps ON ((s.play_status_raw = mps.raw_value)) LEFT JOIN map_storage_location AS msl ON ((s.storage_location_raw = msl.raw_value));
